import sys, os, zlib, base64, importlib.abc, importlib.util

def _zyh_recover():
    """Si una actualización recién instalada no llegó a arrancar bien, se restaura la versión anterior y se reinicia."""
    try:
        import json, shutil
        p = os.path.join(os.path.expanduser("~"), ".zyh_business", "update_state.json")
        st = json.load(open(p, encoding="utf-8"))
        if st.get("pending") and st.get("target") == os.path.abspath(__file__):
            if st.get("booted", 0) >= 1 and os.path.exists(st.get("backup", "")):
                shutil.copy2(st["backup"], st["target"]); st["pending"] = False; st["restored"] = True
                json.dump(st, open(p, "w", encoding="utf-8")); os.execv(sys.executable, [sys.executable, st["target"]] + sys.argv[1:])
            st["booted"] = st.get("booted", 0) + 1; json.dump(st, open(p, "w", encoding="utf-8"))
    except Exception:
        pass
